  "items": [
    {
      "title": "GESIS – German State Election Studies (Landtagswahlen), 1962–Present",
      "url_or_doi": "https://www.gesis.org/en/elections/german-state-elections",
      "justification": "One of the most relevant collections for studying political systems, political parties, electoral behavior, and state-level democracy in Germany during the 1990s. Maintained by GESIS – Leibniz Institute for the Social Sciences, it provides election-related survey datasets covering Berlin, Baden-Württemberg, Bavaria, Bremen, Hesse, Hamburg, Lower Saxony, North Rhine-Westphalia, Rhineland-Palatinate, Saarland, and Schleswig-Holstein. The collection includes studies of voting intentions, party preferences, political attitudes, and electoral participation. Individual datasets can be identified by their GESIS study numbers (ZA)."
    },
    {
      "title": "GESIS – German Federal State Election Studies Integrated Dataset, 1964–2004",
      "url_or_doi": "https://doi.org/10.4232/1.12389",
      "justification": "A particularly valuable dataset for comparative research on German state politics during the 1990s. It integrates historical state election surveys into a harmonized dataset, enabling comparisons of political preferences, voting behavior, party identification, and electoral attitudes across German federal states and election years. Its coverage includes the entire 1990–1999 period within a longer historical series, making it suitable for investigating regional political differences and changes in electoral behavior."
    },
    {
      "title": "Konrad-Adenauer-Stiftung – Historical German Federal and State Election Results Since 1946",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides historical electoral datasets for all eleven requested German federal states, with coverage extending throughout the 1990s. The datasets contain party vote shares, parliamentary seat distributions, electoral participation, and demographic voting patterns where available. Particularly useful for analyzing political party competition, parliamentary representation, the relative strength of political organizations, and changes in regional political systems following German reunification."
    },
    {
      "title": "German Election Database (GERDA) – Historical State Election Results",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "A comprehensive database of German election results at multiple administrative levels. Its historical state election dataset covers elections from 1946 onward, including those held between 1990 and 1999 in the requested federal states. It provides party vote shares at the municipal level, with harmonized geographical versions available from 1990 onward. Particularly useful for geographically detailed comparisons of political party support, regional electoral competition, and long-term political change."
    },
    {
      "title": "GERDA – Harmonized German State Election Results, 1990–Present",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "The harmonized state election component of GERDA provides municipality-level party vote shares beginning in 1990. It includes historical electoral results standardized to common municipal boundaries, facilitating comparisons across time despite administrative boundary changes. Researchers can use it to investigate geographical patterns of political support during the 1990s, including differences between urban states such as Berlin, Bremen, and Hamburg and larger territorial states such as Bavaria and North Rhine-Westphalia."
    },
    {
      "title": "German Election Database (GERDA) – Federal Election Results at the Municipal Level",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Contains geographically detailed German federal election results, including elections held in 1990, 1994, and 1998. Data can be used to compare political party support and electoral participation across the eleven requested federal states. Particularly relevant for understanding the relationships between federal and regional political competition, patterns of party organization, and the electoral consequences of German reunification during the 1990s."
    },
    {
      "title": "GESIS – Berlin House of Representatives Election Study 1995 (ZA2649)",
      "url_or_doi": "https://www.gesis.org/wahlen/landtagswahlen",
      "justification": "A historical election study specifically concerning the 1995 election to Berlin's House of Representatives (Abgeordnetenhaus). Listed in the GESIS state election study collection under study number ZA2649. Relevant for research on Berlin's political parties, electoral preferences, and democratic representation during the first decade following German reunification. It provides a focused source for examining political developments in Berlin during the mid-1990s."
    },
    {
      "title": "GESIS – Berlin House of Representatives Election Study 1999 (ZA3894)",
      "url_or_doi": "https://www.gesis.org/wahlen/landtagswahlen",
      "justification": "An election study associated with the 1999 Berlin House of Representatives election, catalogued by GESIS as ZA3894. It is relevant for studying voter preferences, political competition, and the electoral environment in Berlin at the end of the 1990s. It can be used alongside the 1995 Berlin election study to investigate changes in the city's political landscape."
    },
    {
      "title": "Federal Returning Officer – Historical Elections to German State Parliaments",
      "url_or_doi": "https://bundeswahlleiterin.de/en/service/landtagswahlen.html",
      "justification": "An official German electoral information source providing access to historical state parliamentary election results and references to the responsible state electoral authorities. Relevant to all eleven requested states and their elections during the 1990s. Useful for examining electoral outcomes, political party representation, and changes in parliamentary composition. The historical election results are primarily available in German."
    },
    {
      "title": "GESIS – German Federal Elections, 1949–2005",
      "url_or_doi": "https://www.gesis.org/wahlen",
      "justification": "A collection of German federal election studies covering the 1990, 1994, and 1998 Bundestag elections. The surveys provide information on electoral behavior, political attitudes, voting intentions, and party preferences. Where the underlying datasets provide suitable geographical identifiers, researchers can investigate regional political differences among the eleven requested states. Particularly useful for comparing political attitudes and party support across the 1990s."
    },
    {
      "title": "GESIS – Politbarometer Political Opinion Surveys, 1977–Present",
      "url_or_doi": "https://www.gesis.org/wahlen",
      "justification": "A long-running collection of German political opinion surveys that includes the entire 1990s. Relevant variables concern political attitudes, party preferences, government evaluations, and voting intentions. Depending on the geographical information available in individual survey waves, the data can support comparisons across German federal states. Particularly suitable for studying changes in political trust, public support for governing parties, and citizens' evaluations of political institutions."
    },
    {
      "title": "GESIS – Forsa-Bus Political and Social Surveys, Since 1991",
      "url_or_doi": "https://www.gesis.org/wahlen",
      "justification": "A collection of German survey data beginning in 1991 and covering much of the requested decade. The surveys include political and social attitudes and can provide evidence about public opinion and political preferences during the 1990s. Individual waves should be examined for relevant questions and geographical identifiers before conducting state-level comparisons. Useful as a supplementary source for studying political participation and attitudes toward political organizations."
    },
    {
      "title": "GESIS – ARD DeutschlandTREND Political Opinion Surveys, Since 1998",
      "url_or_doi": "https://www.gesis.org/wahlen",
      "justification": "A collection of German political opinion research beginning in 1998, covering the final years of the requested period. Relevant for studying citizens' evaluations of government performance, political parties, political leaders, and important public policy issues. State-level analysis depends on the geographical variables and sample sizes available in individual studies. Particularly useful for investigating political attitudes around the 1998 federal election."
    },
    {
      "title": "German Election Database (GERDA) – Historical Municipal Election Results",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Provides historical German local election data, including municipal council elections from the 1990s where records are available. Particularly relevant for studying local government, political representation, and the organization of party competition below the state level. The database allows researchers to investigate variation in local electoral outcomes across municipalities within the requested German states. Coverage should be checked for each state and election year."
    },
    {
      "title": "German Election Database (GERDA) – Historical District and Local Political Elections",
      "url_or_doi": "https://github.com/awiedem/german_election_data",
      "justification": "The research repository for GERDA documents datasets covering German electoral competition at municipal, district, state, and federal levels. It includes historical data relevant to political institutions and local government during the 1990s. Particularly useful for research examining the territorial organization of political competition, local democratic representation, and geographical differences in party support. The repository also provides documentation explaining geographical harmonization and dataset coverage."
    },
    {
      "title": "GESIS Research Data Center Elections – Historical German Electoral Survey Archive",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "A research data center providing access to historical German federal and state election survey datasets, including election studies covering the 1990s. The archive brings together multiple relevant collections, such as German state election studies, federal election studies, Politbarometer, and Forsa-Bus. It is especially useful for identifying additional datasets about political parties, political participation, voting behavior, and public attitudes toward government institutions in the eleven requested states."
    }
  ]
}
